//    Al encontrarlo, muestra "Agotado: {nombre}" y para.
echo "--- Con BREAK ---\n";
foreach ...

// b) Con CONTINUE: muestra solo los productos con precio &lt;= 50 €
echo "--- Con CONTINUE (precio &lt;= 50 €) ---\n";
foreach ...
?&gt;
