    echo "Producto: $productoSeguro (ref. $ref)\n";
    echo "Cantidad: $cantidad × " . number_format($precioFinal, 2, ',', '.') . " € = "
       . number_format($total, 2, ',', '.') . " €\n";
    if ($descuento &gt; 0) {
        echo "Descuento aplicado: $descuento%\n";
    }
} else {
    foreach ($errores as $e) {
        echo "Error: " . htmlspecialchars($e, ENT_QUOTES, 'UTF-8') . "\n";
    }
}
?&gt;
