Emitir tokens: la ruta de login
El modelo User debe incorporar el trait HasApiTokens (compruébalo; los proyectos nuevos ya lo traen tras instalar la API):
// app/Models/User.php
use Laravel\Sanctum\HasApiTokens;

class User extends Authenticatable
{
    use HasApiTokens, HasFactory, Notifiable;
    // ...
}
// routes/api.php
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Hash;
use App\Models\User;

Route::post('/login', function (Request $request) {
    $request-&gt;validate([
        'email'    =&gt; 'required|email',
        'password' =&gt; 'required',
    ]);

    $user = User::where('email', $request-&gt;email)-&gt;first();

    if (! $user || ! Hash::check($request-&gt;password, $user-&gt;password)) {
        return response()-&gt;json(
            ['message' =&gt; 'Credenciales incorrectas'], 401
        );
    }

    $token = $user-&gt;createToken(
        'cliente-api',
        $user-&gt;es_admin ? ['juegos:escribir'] : ['juegos:leer']
    );

    return response()-&gt;json([
        'token' =&gt; $token-&gt;plainTextToken,
    ]);
});
