Consumir nuestra propia API autenticada
El ciclo completo contra la API de la tienda: login programático, uso del token y gestión de cada código de estado.
use Illuminate\Support\Facades\Http;

$base = 'http://localhost:8000';

// 1. Obtener el token
$login = Http::acceptJson()-&gt;post("$base/api/login", [
    'email'    =&gt; 'admin@tienda.test',
    'password' =&gt; 'secreto123',
]);

if ($login-&gt;status() === 401) {
    exit('Credenciales incorrectas');
}

$token = $login-&gt;json('token');

// 2. Usarlo en las peticiones siguientes
$creacion = Http::withToken($token)-&gt;acceptJson()
    -&gt;timeout(3)
    -&gt;post("$base/api/juegos", [
        'titulo' =&gt; 'Baldur\'s Gate 3',
        'precio' =&gt; 59.99,
        'genero' =&gt; 'RPG',
    ]);

// 3. Reaccionar según el código
match (true) {
    $creacion-&gt;status() === 201 =&gt;
        print('Creado con id ' . $creacion-&gt;json('data.id')),
    $creacion-&gt;status() === 403 =&gt;
        print('Tu token no permite escritura'),
    $creacion-&gt;status() === 422 =&gt;
        print_r($creacion-&gt;json('errors')),
    default =&gt;
        print('Error inesperado: ' . $creacion-&gt;status()),
};
