// api/valoraciones.php — recibe POST del formulario
header('Content-Type: application/json; charset=utf-8');

$errores = [];
$autor = trim($_POST['autor'] ?? '');
$nota  = filter_var($_POST['nota'] ?? '', FILTER_VALIDATE_INT,
         ['options' =&gt; ['min_range' =&gt; 0, 'max_range' =&gt; 10]]);
$texto = trim($_POST['texto'] ?? '');

if (mb_strlen($autor) &lt; 3)  { $errores['autor'] = 'Mínimo 3 caracteres'; }
if ($nota === false)        { $errores['nota']  = 'Entero entre 0 y 10'; }
if (mb_strlen($texto) &lt; 15) { $errores['texto'] = 'Mínimo 15 caracteres'; }

if ($errores) {
    http_response_code(422);
    echo json_encode(['ok' =&gt; false, 'errores' =&gt; $errores]);
    exit;
}

http_response_code(201);
echo json_encode(['ok' =&gt; true, 'autor' =&gt; htmlspecialchars($autor)]);
Y el cliente que envía y trata el veredicto:
async function enviarValoracion(datos) {
  const r = await fetch('api/valoraciones.php', {
    method: 'POST',
    body: datos
  });
  const cuerpo = await r.json();
  if (r.status === 422) {
    mostrarErrores(cuerpo.errores);
  } else if (r.status === 201) {
    form.reset();
    document.querySelector('#errores').textContent =
      'Gracias, ' + cuerpo.autor + '. Valoración registrada.';
  }
}






TipAnalogía Java



filter_var(..., FILTER_VALIDATE_INT) devuelve false en silencio: en Java, Integer.parseInt("veinte") lanza excepción. En PHP hay que comprobar === false explícitamente.

Pintar errores campo a campo
Cuando el servidor responde 422 con un objeto de errores, el cliente los muestra junto a cada campo. Implementación sencilla de la función mostrarErrores():
function mostrarErrores(errores) {
  // Limpiar avisos anteriores
  form.querySelectorAll('.aviso-campo').forEach(el =&gt; el.remove());

  for (const [campo, mensaje] of Object.entries(errores)) {
    const input = form.elements[campo];
    const aviso = document.createElement('small');
    aviso.className = 'aviso-campo';
    aviso.style.color = 'red';
    aviso.textContent = mensaje;
    input.after(aviso);
  }
}
Con la respuesta 422 del ejemplo anterior, el usuario ve cada campo:
[autor]  Mínimo 3 caracteres
