Contrato mínimo: timeout + try/catch + registro en log:
use GuzzleHttp\Exception\RequestException;
use Illuminate\Support\Facades\Log;

try {
    $r = $cliente-&gt;get('/search.json', ['query' =&gt; ['q' =&gt; 'laravel']]);
    $datos = json_decode($r-&gt;getBody(), true);
} catch (RequestException $e) {
    Log::error('Fallo: ' . $e-&gt;getMessage());
    abort(503, 'Fuente no disponible.');
}
